/**
 * @fileoverview The Studio's Starters gallery: each starter's picture, its
 * params as a schema for `lcards-astro-schema-form`, and what it adds.
 *
 * Pictures are generated by `scripts/astro-pictures.mjs` into
 * `src/assets/images/astro-studio/` (copied to custom_components/lcards/images/
 * by the build, served at /lcards/images/),
 * never bundled.
 */

import { applyStarter } from '../../../core/astrometrics/starters/index.js';

/** Where the Studio's generated pictures are served */
export const PICTURE_BASE = '/lcards/images/astro-studio/';

/**
 * A starter's picture URL.
 * @param {string} id
 */
export function starterPicture(id) {
  return `${PICTURE_BASE}starter-${id}.webp`;
}

/** A point id or [x, y, z]: the schema shape the form shows as a point picker */
const POINT_SCHEMA = { oneOf: [{ type: 'string' }, { type: 'array', items: { type: 'number' }, minItems: 3, maxItems: 3 }] };

/**
 * A starter's params as form properties, by key.
 * @param {import('../../../core/astrometrics/starters/index.js').Starter} starter
 * @returns {Record<string, any>}
 */
export function starterParamSchema(starter) {
  /** @type {Record<string, any>} */
  const out = {};
  for (const p of starter.params) {
    const hints = { 'x-ui-hints': { label: p.label } };
    const description = p.helper;
    if (p.type === 'number') out[p.key] = { type: 'number', description, ...hints };
    else if (p.type === 'point') out[p.key] = { ...POINT_SCHEMA, description, ...hints };
    // a fixed list: a dropdown with each option's name (a list that takes other values too is a text field with choices)
    else if (p.options?.length && !p.custom) {
      out[p.key] = {
        type: 'string', enum: p.options.map((o) => o.value), default: p.default, description, ...hints,
        enumDescriptions: Object.fromEntries(p.options.map((o) => [o.value, o.label]))
      };
    } else out[p.key] = { type: 'string', description, ...hints };
  }
  return out;
}

/**
 * Dropdown words for params that take a list or anything typed (the form's `choices`).
 * @param {import('../../../core/astrometrics/starters/index.js').Starter} starter
 * @returns {Record<string, string[]>}
 */
export function starterParamChoices(starter) {
  return Object.fromEntries(starter.params.filter((p) => p.options?.length && p.custom).map((p) => [p.key, (p.options ?? []).map((o) => o.value)]));
}

/**
 * The params to show: each default, then what was typed over it.
 * @param {import('../../../core/astrometrics/starters/index.js').Starter} starter
 * @param {Record<string, any>} [typed]
 */
export function starterParamValues(starter, typed = {}) {
  return { ...Object.fromEntries(starter.params.map((p) => [p.key, p.default])), ...typed };
}

/**
 * What a fragment holds, in words ("12 points, 6 objects, 3 views"), or ''.
 * @param {import('../../../core/astrometrics/starters/index.js').StarterFragment} frag
 */
export function fragmentCounts(frag) {
  const n = (/** @type {number} */ c, /** @type {string} */ word) => (c ? `${c} ${word}${c === 1 ? '' : 's'}` : null);
  return [
    n(frag.points?.length ?? 0, 'point'),
    n(frag.objects?.length ?? 0, 'object'),
    n(Object.keys(frag.views ?? {}).length, 'view')
  ].filter(Boolean).join(', ');
}

/**
 * What a starter adds with these params, in words, or its error.
 * @param {import('../../../core/astrometrics/starters/index.js').Starter} starter
 * @param {Record<string, any>} [typed]
 */
export function starterAdds(starter, typed = {}) {
  const out = applyStarter({}, starter, typed);
  return out.added ? fragmentCounts(out.added) : String(out.error);
}
